        "A bleiben akkor használatos, ha egy személy vagy dolog nem megy el, és ugyanazon a helyen vagy állapotban marad.",
        "Ez a gehen és a fahren ellentéte, amikor az eltávozásról van szó.",
        "Nagyon gyakori kifejezés az Ich bleibe zu Hause."
