    "de": "euch",
    "lv": "Te • Te",
    "level": "A1",
    "study": {
      "id": "a1-euch",
      "layout": "standardStudy",
      "translation": "Te • Te",
      "explanation": "Az „euch” többes szám 2. személyű névmás. Közvetlen kiegészítésként (hol?) - \"te\" és közvetett kiegészítésként (kinek?) - \"neked\" egyaránt használatos.",
      "examples": [
        {
          "de": "Ich sehe euch.",
          "lv": "Látlak"
        },
        {
          "de": "Ich helfe euch.",
          "lv": "Segítek neked"
        },
        {
          "de": "Ich gebe euch das Buch.",
          "lv": "Adok egy könyvet"
        },
        {
          "de": "Ich danke euch.",
          "lv": "Én köszönöm"
        },
        {
          "de": "Ihr erinnert euch.",
          "lv": "Emlékszel"
        }
      ],
      "comparison": [
        {
          "word": "ihr",
          "meaning": "Te",
          "example": "Ihr seid freundlich. = Jūs esat draudzīgi."
        },
        {
          "word": "euch",
          "meaning": "Neked / neked",
          "example": "Ich helfe euch. = Es jums palīdzu."
        },
        {
          "word": "euer",
          "meaning": "A tiéd",
          "example": "Das ist euer Haus. = Tā ir jūsu māja."
        }
      ],
      "info": [
        "ihr = jūs (teikuma priekšmeta forma)",
        "euch = jūs (kurp? forma) / jums (kam? forma)",
        "euer = jūsu (piederības forma)"
      ],
      "tip": {
        "text": "“euch” atbild uz jautājumu “kam?” vai ir tiešais papildinājums teikumos ar “jūs”.",
        "example": "Es jums palīdzu. = Ich helfe euch. Es redzu jūs. = Ich sehe euch. Es stāstu jums. = Ich erzähle euch."
      },
      "accents": {
        "blue": [
          "ihr"
        ],
        "yellow": [
          "euch"
        ],
        "green": [
          "euer"
        ]
      }
    }
