      "id": "a1-land",
      "layout": "standardStudy",
      "translation": "Ország • Föld",
      "explanation": [
        "Fő gondolat: das Land legtöbbször országot vagy városon kívüli földet jelent.",
        "Ha Németországról, Lettországról vagy más határokkal rendelkező területről van szó, akkor országnak fordítják.",
        "Amikor vidékről vagy földről beszélünk a várossal szemben, fordítsuk vidéknek vagy földnek.",
        "A szövegkörnyezet határozza meg, hogy országra, vidékre vagy földre gondolunk."
      ],
      "examples": [
        {
          "de": "Deutschland ist ein schönes Land.",
          "lv": "Németország gyönyörű ország."
        },
        {
          "de": "Ich komme aus einem kleinen Land.",
          "lv": "Kis országból származom."
        },
        {
          "de": "Wir fahren aufs Land.",
          "lv": "Vidékre megyünk."
        },
        {
          "de": "Auf dem Land ist es ruhig.",
          "lv": "Vidéken csend van."
        }
      ],
