        "Morgen főként azt jelenti: másnap.",
        "Gyakran jellemző: időjárás.",
        "Morgen elsősorban azt jelenti: a nap egy részét.",
        "Gyakran leírja: főnév (der).",
        "Morgen alapvetően azt jelenti: több reggel.",
        "Gyakran jellemzi: főnév (pl.).",
