        "Amikor egy helyről, helyzetről vagy személyről beszélünk, sicher = biztonságos (ein sicherer Ort = biztonságos hely).",
        "Egy mondatban megerősítésként vagy biztosítékként sicher = biztosan/természetesen (Das ist sicher wahr. = Bizonyára igaz.).",
