        "Emberekről kérdeztünk, nem dolgokról vagy eseményekről.",
        "A dolgokat és az eseményeket was-vel kérdezik, nem werrel.",
        "Wer a németben általában egy mondat alanya (névképző) – Wer ist das? = Mi az?",
        "Amikor azt kérdezzük, hogy a több ember közül melyiket, a wer-t gyakran a von-nal használják (wer von euch = melyikőtök).",
        "A wer ragozás szerint változtatja a formát: wen (akkuzatív), wem (datív), wessen (genitivus) - pontosan a wer alak a leggyakoribb A1 szinten."
