      "explanation": [
        "A zum a zu elöljárószó és a dem szócikk rövidítése.",
        "Teljes forma: zu dem (kinek?).",
        "Hímnemű és semleges főnevekkel együtt használatos az irány vagy a cél jelzésére.",
        "Gyakran jelent valaminek vagy valakinek - az orvosnak, az állomásnak, egy barátnak.",
        "A gyakorlatban szinte mindig a zum-ot használják a full zu dem helyett."
      ],
      "examples": [
        {
          "de": "Ich gehe zum Arzt.",
          "lv": "Megyek az orvoshoz."
        },
        {
          "de": "Wir fahren zum Bahnhof.",
          "lv": "Megyünk az állomásra."
        },
        {
          "de": "Sie geht zum Supermarkt.",
          "lv": "Elmegy a boltba."
        },
        {
          "de": "Komm zum Essen!",
          "lv": "Gyere enni!"
        },
        {
          "de": "Er fährt zum Flughafen.",
          "lv": "A repülőtérre megy."
        },
        {
          "de": "Wir gehen zum Konzert.",
          "lv": "Koncertre megyünk."
        },
        {
          "de": "Das Geschenk ist zum Geburtstag.",
          "lv": "Az ajándék születésnapra szól."
        },
        {
          "de": "Ich gehe zum Friseur.",
          "lv": "Megyek fodrászhoz."
        }
      ],
      "comparison": [
        {
          "word": "zum",
          "meaning": "Kinek / kinek (kinek?)",
          "example": "zum Arzt – Az orvoshoz"
        },
        {
          "word": "zur",
          "meaning": "(feleség családjához)",
          "example": "zur Schule – Iskolába"
        },
        {
          "word": "zu",
          "meaning": "To / at / is",
          "example": "zu Hause – Otthon"
        },
        {
          "word": "nach",
          "meaning": "Ide (városok/országok)",
          "example": "nach Berlin – Berlinbe"
        },
        {
          "word": "bei",
          "meaning": "Itt (helyszín)",
          "example": "beim Arzt – Az orvoshoz"
        }
      ],
      "tip": [
        "Atceries: zu + dem → zum (kam?).",
        "Sievišķās dzimtes vārdiem: zu + der → zur."
      ],
      "important": [
        "zum = zu dem, tikai ar vīriešu vai nekatras dzimtes lietvārdu kam? locījumā.",
        "Norāda virzienu vai mērķi: pie ārsta, uz staciju, pie drauga.",
        "Sievišķās dzimtei lieto zur: zur Bank, zur Post.",
        "Nesajauc ar bei (atrašanās pie) vai nach (uz pilsētām bez artikula)."
      ],
